import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as s,af as n}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const m=JSON.parse('{"title":"Agent Plugins（观察）","description":"把 Skills 与 MCP server 打包成一个可分发的插件包——Agent Plugins 1.0.0 是 package/conformance 规范（manifest、固定发现位置、路径包含），不含权限、沙箱、registry 与执行引擎；观察卡，未升格 canonical。","frontmatter":{"title":"Agent Plugins（观察）","description":"把 Skills 与 MCP server 打包成一个可分发的插件包——Agent Plugins 1.0.0 是 package/conformance 规范（manifest、固定发现位置、路径包含），不含权限、沙箱、registry 与执行引擎；观察卡，未升格 canonical。","domain":"tech","tags":["tech","action","plugins","watchlist"],"navOrder":68,"topicId":"plugins","layer":"6","status":"watchlist","nodeType":"concept","owner":"learn-ai","externalOwners":[],"prerequisites":["skills","mcp"],"next":["protocol-map"],"specVersion":"Agent Plugins 1.0.0","lastVerified":"2026-09-01","bilingualParity":"exact","listed":true},"headers":[],"relativePath":"zh/tech/06-agent-systems/plugins.md","filePath":"zh/tech/06-agent-systems/plugins.md","lastUpdated":1791115887000}'),i={name:"zh/tech/06-agent-systems/plugins.md"};function o(l,t,r,d,c,h){return s(),a("div",null,[...t[0]||(t[0]=[n(`<blockquote><p><strong>所在组</strong>：Agent 系统 ｜ <strong>上一组出口</strong>：能把模型输出接入会话与状态 ｜ <strong>本页出口</strong>：能判断「打包分发」何时需要 Agent Plugins、它管什么与不管什么 <strong>前置</strong>：<a href="./skills.html">Agent Skills</a>、<a href="./../07-interoperability/mcp.html">MCP</a> ｜ <strong>下一步</strong>：<a href="./../07-interoperability/">协议地图</a></p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p><strong>结论先讲</strong>：当你需要把<strong>一组</strong>能力（若干 Skills + 若干 MCP server 配置）作为<strong>一个可分发单元</strong>交给别人安装时，Agent Plugins 1.0.0 定义了这个包的格式契约：根目录 <code>plugin.json</code> 清单、固定发现位置（<code>skills/</code> 与 <code>mcp.json</code>）、路径包含规则与 <code>\${PLUGIN_ROOT}</code>/<code>\${PLUGIN_DATA}</code> 变量。它是 <strong>package/conformance 规范</strong>——规定「包长什么样、客户端怎么校验与发现」，<strong>不是</strong>执行、权限或分发基础设施。本页是观察卡（watchlist）：learn-ai 尚未在生产依赖它。</p><h3 id="心智模型-一个插件包" tabindex="-1">心智模型：一个插件包 <a class="header-anchor" href="#心智模型-一个插件包" aria-label="Permalink to &quot;心智模型：一个插件包&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-plugin/</span></span>
<span class="line"><span>├── plugin.json          # 必需：封闭 schema 清单（$schema、name 必填）</span></span>
<span class="line"><span>├── skills/              # 固定位置①：每个直接子目录一个 Skill（内含 SKILL.md）</span></span>
<span class="line"><span>│   └── summarize/</span></span>
<span class="line"><span>│       └── SKILL.md</span></span>
<span class="line"><span>├── mcp.json             # 固定位置②：MCP server 连接配置（stdio / streamable-http / sse）</span></span>
<span class="line"><span>├── com.example.client/  # 客户端扩展目录（反向域名命名空间）</span></span>
<span class="line"><span>└── LICENSE</span></span></code></pre></div><p>两层关系：<strong>Skill 格式由 Agent Skills 规范拥有；Plugins 只定义如何在包内发现 Skill</strong>（<code>skills/</code> 下的直接子目录，不递归深层搜索）。MCP 的线上行为由 MCP 规范拥有；Plugins 只定义 <code>mcp.json</code> 的可移植配置格式。</p><h3 id="何时使用-何时不用" tabindex="-1">何时使用 / 何时不用 <a class="header-anchor" href="#何时使用-何时不用" aria-label="Permalink to &quot;何时使用 / 何时不用&quot;">​</a></h3><ul><li>用：向多客户端分发「技能 + 工具连接」的组合包；内部工具链要一个安装单元。</li><li>不用： <ul><li>单个技能 → 直接用 <a href="./skills.html">Skills</a>，无需包；</li><li>只需要工具连接 → 直接配 MCP server；</li><li>需要权限/沙箱/市场审核 → Plugins 规范不提供这些（见下）。</li></ul></li></ul><h3 id="决策表-分发形态怎么选" tabindex="-1">决策表：分发形态怎么选 <a class="header-anchor" href="#决策表-分发形态怎么选" aria-label="Permalink to &quot;决策表：分发形态怎么选&quot;">​</a></h3><table tabindex="0"><thead><tr><th>形态</th><th>方向</th><th>控制权</th><th>状态</th><th>信任域</th><th>最低复杂度</th></tr></thead><tbody><tr><td>单个 Skill 目录</td><td>知识注入</td><td>description 触发</td><td>静态文件</td><td>宿主进程内</td><td>一个文件夹</td></tr><tr><td>Agent Plugin 包</td><td>组合分发</td><td>清单 + 固定发现位置</td><td>静态目录 + 安装态（PLUGIN_DATA）</td><td>宿主进程内，跨包不隔离</td><td>plugin.json + 组件</td></tr><tr><td>MCP server 单独部署</td><td>工具连接</td><td>协议边界 + 授权</td><td>server 进程/会话</td><td>跨进程边界</td><td>一个 server</td></tr></tbody></table><h3 id="它管什么-不管什么-按核验到的规范原文" tabindex="-1">它管什么 / 不管什么（按核验到的规范原文） <a class="header-anchor" href="#它管什么-不管什么-按核验到的规范原文" aria-label="Permalink to &quot;它管什么 / 不管什么（按核验到的规范原文）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>管（v1.0.0 范围内）</th><th>不管（明确不在规范内）</th></tr></thead><tbody><tr><td><code>plugin.json</code> 封闭清单（顶层仅 9 个许可字段；未知字段报告并忽略）</td><td><strong>沙箱</strong>：规范原文明确「路径包含规则……不沙箱化插件子进程，也不限制运行期提供的路径」</td></tr><tr><td>固定发现位置：<code>skills/</code>、<code>mcp.json</code>，清单不能内联组件配置</td><td><strong>权限模型</strong>：无权限字段、无审批流；安全由客户端自行实现</td></tr><tr><td>路径包含：解析后的路径必须留在插件根内；越界按最窄失败边界处理</td><td><strong>registry / 市场</strong>：设计决策明确选择目录式包（可用 <code>ls</code>/<code>git</code> 检查），不是 registry 拉取式</td></tr><tr><td><code>\${PLUGIN_ROOT}</code> / <code>\${PLUGIN_DATA}</code> 变量与子进程环境</td><td><strong>执行引擎</strong>：客户端（plugin runtime）负责发现、安装、加载、执行</td></tr><tr><td>客户端一致性要求（conformance）与组件级非致命失败语义</td><td>治理（另行由 Technical Charter 定义）</td></tr></tbody></table><h3 id="历史版本里程碑" tabindex="-1">历史版本里程碑 <a class="header-anchor" href="#历史版本里程碑" aria-label="Permalink to &quot;历史版本里程碑&quot;">​</a></h3><p>Agent Plugins 1.0.0，状态 Published（2026-09-01 核验）。v1 只定义两种组件类型：<strong>skills 与 MCP servers</strong>；commands、hooks、agents、rules、LSP server 等在规范设计决策中被明确列为「过于客户端特化，不在 v1」。</p><h2 id="_2-使用" tabindex="-1">2. 使用 <a class="header-anchor" href="#_2-使用" aria-label="Permalink to &quot;2. 使用&quot;">​</a></h2><p>观察卡的最小实战：手工走一遍清单一致性检查（纸面 + 一个零依赖 JSON 检查，≤15 分钟，无 API key）。</p><h3 id="步骤-1-写一个最小合法清单" tabindex="-1">步骤 1：写一个最小合法清单 <a class="header-anchor" href="#步骤-1-写一个最小合法清单" aria-label="Permalink to &quot;步骤 1：写一个最小合法清单&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;$schema&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://agent-plugins.org/schemas/1.0.0/plugin.schema.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;minimal-plugin&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>$schema</code> 与 <code>name</code> 是仅有的必填字段。<code>name</code> 规则：1-64 字符；仅 <code>a-z</code>、<code>0-9</code>、<code>-</code>、<code>.</code>；首尾必须是字母数字；不允许 <code>--</code> 与 <code>..</code>。</p><h3 id="步骤-2-零依赖检查必填字段与命名规则" tabindex="-1">步骤 2：零依赖检查必填字段与命名规则 <a class="header-anchor" href="#步骤-2-零依赖检查必填字段与命名规则" aria-label="Permalink to &quot;步骤 2：零依赖检查必填字段与命名规则&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input-type=module</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">import { readFileSync } from &quot;node:fs&quot;;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">const m = JSON.parse(readFileSync(&quot;plugin.json&quot;, &quot;utf-8&quot;));</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">const failures = [];</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">if (m.$schema !== &quot;https://agent-plugins.org/schemas/1.0.0/plugin.schema.json&quot;)</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  failures.push(&quot;$schema must be the 1.0.0 canonical identifier&quot;);</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">if (!/^[a-z0-9]([a-z0-9.-]*[a-z0-9])?$/.test(m.name ?? &quot;&quot;) || (m.name ?? &quot;&quot;).length &gt; 64</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    || /--|\\.\\./.test(m.name ?? &quot;&quot;))</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  failures.push(&quot;name violates 1.64/charset/no----or-.. rules&quot;);</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">const allowed = [&quot;$schema&quot;,&quot;name&quot;,&quot;version&quot;,&quot;description&quot;,&quot;author&quot;,&quot;homepage&quot;,&quot;repository&quot;,&quot;license&quot;,&quot;keywords&quot;,&quot;extensions&quot;];</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">for (const k of Object.keys(m)) if (!allowed.includes(k)) failures.push(\`unknown top-level field: \${k}\`);</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">console.log(failures.length ? \`FAIL \${failures.join(&quot;; &quot;)}\` : &quot;PASS minimal manifest conforms&quot;);</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">process.exit(failures.length ? 1 : 0);</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;</span></span></code></pre></div><p>正常输出：<code>PASS minimal manifest conforms</code>（退出码 0）。</p><h3 id="步骤-3-负例" tabindex="-1">步骤 3：负例 <a class="header-anchor" href="#步骤-3-负例" aria-label="Permalink to &quot;步骤 3：负例&quot;">​</a></h3><p>把 <code>&quot;name&quot;</code> 改成 <code>&quot;My-Plugin&quot;</code>（大写非法）再跑：输出 <code>FAIL name violates 1.64/charset/no----or-.. rules</code>，退出码 1。</p><h3 id="验收与清理" tabindex="-1">验收与清理 <a class="header-anchor" href="#验收与清理" aria-label="Permalink to &quot;验收与清理&quot;">​</a></h3><p>验收：正例退出 0、负例退出 1。清理：删除临时 <code>plugin.json</code>。本页无宿主接入步骤——learn-ai 未在任何生产链路消费 Agent Plugins，接入经验留空待补。</p><h2 id="_3-原理" tabindex="-1">3. 原理 <a class="header-anchor" href="#_3-原理" aria-label="Permalink to &quot;3. 原理&quot;">​</a></h2><h3 id="发现与失败边界" tabindex="-1">发现与失败边界 <a class="header-anchor" href="#发现与失败边界" aria-label="Permalink to &quot;发现与失败边界&quot;">​</a></h3><ul><li>组件只从固定位置发现：<code>skills/</code>（每个<strong>直接</strong>子目录内含 <code>SKILL.md</code> 即一个技能，不递归）、<code>mcp.json</code>（唯一 MCP 配置入口，禁止内联进清单）。</li><li>失败按最窄边界隔离：单个技能不合规→跳过该技能；单个 server 条目不合规→跳过该 server；<code>mcp.json</code> 整体不合规→仅禁用该插件的 MCP；<strong>清单本身违反 schema（必填字段错误等）→ 整包拒绝</strong>。固定位置缺失不是错误。</li><li>路径包含：配置中的包内路径必须以 <code>./</code> 开头且解析后留在插件根内（<code>../bin/server</code> 非法）；<code>command</code> 是单个可执行 token，不是 shell 字符串。</li></ul><h3 id="规范要求-vs-本地实测" tabindex="-1">规范要求 vs 本地实测 <a class="header-anchor" href="#规范要求-vs-本地实测" aria-label="Permalink to &quot;规范要求 vs 本地实测&quot;">​</a></h3><table tabindex="0"><thead><tr><th>规范要求（Agent Plugins 1.0.0，2026-09-01 核验）</th><th>本地实测（第 2 节 fixture）</th></tr></thead><tbody><tr><td>必填 <code>$schema</code>（canonical 标识符）与 <code>name</code></td><td>检查脚本第 1、2 组断言</td></tr><tr><td>name 字符集/长度/首尾/重复规则</td><td>负例 <code>My-Plugin</code> 被捕获</td></tr><tr><td>顶层字段封闭，未知字段报告并忽略</td><td>检查脚本列出未知字段</td></tr><tr><td>v1 组件类型仅 skills + MCP servers</td><td>fixture 未覆盖组件发现（无生产需求，留观察）</td></tr></tbody></table><h3 id="与-skills-mcp-的所有权分层" tabindex="-1">与 Skills / MCP 的所有权分层 <a class="header-anchor" href="#与-skills-mcp-的所有权分层" aria-label="Permalink to &quot;与 Skills / MCP 的所有权分层&quot;">​</a></h3><p>一条事实只有一个 owner：Skill 格式 → agentskills.io；MCP 线上行为 → MCP 规范；<strong>Plugins 只拥有「包与发现」这一层</strong>。读文档时用这个分层判断「某字段去哪查」。</p><h2 id="_4-开发" tabindex="-1">4. 开发 <a class="header-anchor" href="#_4-开发" aria-label="Permalink to &quot;4. 开发&quot;">​</a></h2><p>观察卡：以下 runbook 是「若你决定试点」的预习，不是本仓已验证经验。</p><h3 id="症状-→-证据-→-处理-→-完成标准" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：客户端加载插件时整包被拒。 <strong>证据</strong>：客户端报告的无效字段指向 <code>plugin.json</code>；对照发现必填字段缺失或类型错误（未知顶层字段不会导致拒绝——只有其他 schema 违反才会）。 <strong>处理</strong>：修复清单本身；未知字段移到 <code>extensions.&lt;反向域名&gt;</code> 命名空间下。 <strong>完成标准</strong>：客户端日志只余组件级警告（若有），包被加载。</p><h3 id="症状-→-证据-→-处理-→-完成标准-1" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准-1" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：插件里的 MCP server 起不来，但技能正常。 <strong>证据</strong>：<code>mcp.json</code> 的 server 条目不合规（如 <code>command</code> 写成 shell 串、<code>cwd</code> 越界）或与 <code>plugin.json</code> 的 <code>$schema</code> 版本不一致。 <strong>处理</strong>：按 7.2 节修复该条目（<code>command</code> 单 token、<code>./</code> 相对路径、占位符仅 <code>\${PLUGIN_ROOT}</code>/<code>\${PLUGIN_DATA}</code>）；版本对齐。 <strong>完成标准</strong>：该 server 能完成 MCP 握手；其余组件不受影响。</p><h3 id="症状-→-证据-→-处理-→-完成标准-2" tabindex="-1">症状 → 证据 → 处理 → 完成标准 <a class="header-anchor" href="#症状-→-证据-→-处理-→-完成标准-2" aria-label="Permalink to &quot;症状 → 证据 → 处理 → 完成标准&quot;">​</a></h3><p><strong>症状</strong>：升级插件后数据/依赖丢失。 <strong>证据</strong>：把可写状态放在了包目录内——更新时包内容会被整体替换。 <strong>处理</strong>：可写状态全部迁到 <code>\${PLUGIN_DATA}</code>（规范要求客户端跨更新保留该目录）。 <strong>完成标准</strong>：升级插件后缓存、依赖、生成物仍在。</p><h3 id="升格-canonical-的门槛" tabindex="-1">升格 canonical 的门槛 <a class="header-anchor" href="#升格-canonical-的门槛" aria-label="Permalink to &quot;升格 canonical 的门槛&quot;">​</a></h3><p>满足以下任一条件时本页升格为 canonical：learn-ai 或 sibling 站在真实链路消费 Agent Plugins 包；或生态出现≥2 个独立客户端实现一致性声明。在此之前，包格式事实仍以 git 仓库/产品文档为准。</p><h2 id="_5-资料库" tabindex="-1">5. 资料库 <a class="header-anchor" href="#_5-资料库" aria-label="Permalink to &quot;5. 资料库&quot;">​</a></h2><p>四级阅读路线：</p><ul><li><strong>Beginner</strong>：读本页，能复述「管什么/不管什么」表。</li><li><strong>Builder</strong>：读规范 §4–§7，手工搭一个最小包并跑第 2 节检查。</li><li><strong>Operator</strong>：若试点，把清单检查接进发布流水线；跟踪 schema 版本变更。</li><li><strong>Researcher</strong>：读规范 Design Decisions 与 Conformance Checklist，理解「为何 v1 只有两种组件」。</li></ul><h3 id="资源表" tabindex="-1">资源表 <a class="header-anchor" href="#资源表" aria-label="Permalink to &quot;资源表&quot;">​</a></h3><table tabindex="0"><thead><tr><th>名称</th><th>证据层级</th><th>canonical URL</th><th>用途</th><th>支持的断言</th><th>下一步</th></tr></thead><tbody><tr><td>Agent Plugins 规范 1.0.0</td><td>L0（官方规范）</td><td><a href="https://agent-plugins.org/specification" target="_blank" rel="noreferrer">https://agent-plugins.org/specification</a></td><td>包格式契约唯一来源</td><td>清单 schema、固定位置、包含规则、无沙箱/registry（retrievedAt 2026-09-01）</td><td>对照第 1、3 节</td></tr><tr><td>官方 schema（1.0.0）</td><td>L0（官方工件）</td><td><a href="https://agent-plugins.org/schemas/1.0.0/plugin.schema.json" target="_blank" rel="noreferrer">https://agent-plugins.org/schemas/1.0.0/plugin.schema.json</a></td><td>机器可读校验</td><td><code>$schema</code> canonical 标识符（retrievedAt 2026-09-01）</td><td>接入 JSON Schema 校验</td></tr><tr><td>Agent Skills 规范</td><td>L0（官方规范）</td><td><a href="https://agentskills.io/specification" target="_blank" rel="noreferrer">https://agentskills.io/specification</a></td><td>组件①格式 owner</td><td>Skill 格式归 Skills 规范（retrievedAt 2026-09-01）</td><td><a href="./skills.html">Agent Skills</a></td></tr><tr><td>MCP 规范</td><td>L0（官方规范）</td><td><a href="https://modelcontextprotocol.io/specification/latest" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/specification/latest</a></td><td>组件②行为 owner</td><td>MCP 线上行为归 MCP 规范（retrievedAt 2026-09-01）</td><td><a href="./../07-interoperability/mcp.html">MCP</a></td></tr></tbody></table><h3 id="主动证伪与未决问题" tabindex="-1">主动证伪与未决问题 <a class="header-anchor" href="#主动证伪与未决问题" aria-label="Permalink to &quot;主动证伪与未决问题&quot;">​</a></h3><ul><li>证伪入口：若你发现某客户端对同一 <code>plugin.json</code> 的处理与「规范要求 vs 本地实测」表相矛盾，以规范与该客户端文档为准并修订本页。</li><li>未决：生态采用率（无证据不写）；v1 之外组件类型（commands/hooks/agents/rules/LSP）的演进；<code>mcp.json</code> <code>sse</code> 类型随 MCP HTTP+SSE 弃用后的去留。</li></ul><h3 id="learn-ai-到此为止-继续去哪" tabindex="-1">learn-ai 到此为止 / 继续去哪 <a class="header-anchor" href="#learn-ai-到此为止-继续去哪" aria-label="Permalink to &quot;learn-ai 到此为止 / 继续去哪&quot;">​</a></h3><ul><li>组件格式与行为：<a href="./skills.html">Agent Skills</a>、<a href="./../07-interoperability/mcp.html">MCP</a>。</li><li>层 4 协议全景：<a href="./../07-interoperability/">协议地图</a>。</li></ul>`,52)])])}const q=e(i,[["render",o]]);export{m as __pageData,q as default};
